import React, { useEffect, useRef } from 'react'

type FreshnessState = 'fresh' | 'caution' | 'critical'

interface FreshnessDialProps {
  totalHours: number
  remainingHours: number
  size?: number
  label?: string
  animate?: boolean
}

function getState(ratio: number): FreshnessState {
  if (ratio > 0.5) return 'fresh'
  if (ratio > 0.2) return 'caution'
  return 'critical'
}

function formatTime(hours: number): string {
  if (hours >= 24) {
    const d = Math.floor(hours / 24)
    const h = Math.floor(hours % 24)
    return `${d}d ${h}h`
  }
  if (hours >= 1) return `${Math.floor(hours)}h`
  return `<1h`
}

const STATE_COLORS: Record<FreshnessState, { arc: string; text: string; bg: string; icon: string }> = {
  fresh: { arc: '#2F9E5B', text: '#1F6B45', bg: '#E6F4EA', icon: '🌿' },
  caution: { arc: '#F2A93B', text: '#B87A1A', bg: '#FDF1DA', icon: '⚡' },
  critical: { arc: '#E5484D', text: '#C0181D', bg: '#FDE8E8', icon: '🔥' },
}

function describeArc(cx: number, cy: number, r: number, startAngle: number, endAngle: number) {
  const toRad = (a: number) => (a * Math.PI) / 180
  const x1 = cx + r * Math.cos(toRad(startAngle))
  const y1 = cy + r * Math.sin(toRad(startAngle))
  const x2 = cx + r * Math.cos(toRad(endAngle))
  const y2 = cy + r * Math.sin(toRad(endAngle))
  const large = endAngle - startAngle > 180 ? 1 : 0
  return `M ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2}`
}

function describeTicks(cx: number, cy: number, r: number, count: number, startAngle: number, endAngle: number) {
  const ticks = []
  for (let i = 0; i <= count; i++) {
    const angle = startAngle + (i / count) * (endAngle - startAngle)
    const rad = (angle * Math.PI) / 180
    const inner = r - 5
    const outer = r + 1
    const x1 = cx + inner * Math.cos(rad)
    const y1 = cy + inner * Math.sin(rad)
    const x2 = cx + outer * Math.cos(rad)
    const y2 = cy + outer * Math.sin(rad)
    ticks.push(`M ${x1} ${y1} L ${x2} ${y2}`)
  }
  return ticks.join(' ')
}

export function FreshnessDial({ totalHours, remainingHours, size = 160, label, animate = false }: FreshnessDialProps) {
  const ratio = Math.min(1, Math.max(0, remainingHours / totalHours))
  const state = getState(ratio)
  const colors = STATE_COLORS[state]

  const cx = size / 2
  const cy = size * 0.58
  const r = size * 0.38

  const START = 200
  const END = 340
  const RANGE = END - START

  const filledEnd = START + ratio * RANGE

  const trackPath = describeArc(cx, cy, r, START, END)
  const arcPath = ratio > 0 ? describeArc(cx, cy, r, START, filledEnd) : ''
  const tickPath = describeTicks(cx, cy, r, 20, START, END)

  const iconSize = size * 0.18

  return (
    <div
      className="relative flex flex-col items-center"
      style={{ width: size, height: size * 0.75 }}
    >
      <svg width={size} height={size * 0.75} style={{ overflow: 'visible' }}>
        {/* Track */}
        <path d={trackPath} fill="none" stroke="#EEE9DD" strokeWidth={size * 0.07} strokeLinecap="round" />

        {/* Filled arc */}
        {arcPath && (
          <path
            d={arcPath}
            fill="none"
            stroke={colors.arc}
            strokeWidth={size * 0.07}
            strokeLinecap="round"
            style={{ transition: animate ? 'stroke-dashoffset 0.8s ease-out' : 'none' }}
          />
        )}

        {/* Tick marks */}
        <path d={tickPath} stroke="#D4CCBB" strokeWidth={0.75} fill="none" opacity={0.5} />

        {/* Produce icon circle */}
        <circle cx={cx} cy={cy - r * 0.42} r={iconSize * 0.85} fill={colors.bg} />
        <text
          x={cx}
          y={cy - r * 0.42 + iconSize * 0.35}
          textAnchor="middle"
          fontSize={iconSize * 0.9}
          style={{ userSelect: 'none' }}
        >
          {colors.icon}
        </text>

        {/* Time remaining */}
        <text
          x={cx}
          y={cy + size * 0.04}
          textAnchor="middle"
          fontSize={size * 0.185}
          fontFamily="'Fraunces', Georgia, serif"
          fill={colors.text}
          fontWeight={500}
          className={state === 'critical' ? 'animate-pulse-ring' : ''}
        >
          {formatTime(remainingHours)}
        </text>

        {/* Label */}
        <text
          x={cx}
          y={cy + size * 0.14}
          textAnchor="middle"
          fontSize={size * 0.09}
          fontFamily="'DM Sans', sans-serif"
          fill="#6B7568"
        >
          {label || 'freshness left'}
        </text>
      </svg>

      {/* State chip */}
      <div
        className={`absolute bottom-0 px-2 py-0.5 rounded-full text-xs font-medium ${
          state === 'fresh'
            ? 'bg-[#E6F4EA] text-[#1F6B45]'
            : state === 'caution'
            ? 'bg-[#FDF1DA] text-[#B87A1A]'
            : 'bg-[#FDE8E8] text-[#C0181D]'
        }`}
        style={{ fontFamily: "'DM Sans', sans-serif" }}
      >
        {state === 'fresh' ? '● Fresh' : state === 'caution' ? '● Caution' : '● Critical'}
      </div>
    </div>
  )
}

import React from 'react'
import { FreshnessDial } from './FreshnessDial'

export interface Shipment {
  id: string
  code: string
  produce: string
  emoji: string
  origin: string
  destination: string
  totalHours: number
  remainingHours: number
  temperature: number
  tempStatus: 'normal' | 'high'
  progress: number // 0-100
  isNew?: boolean
}

interface ShipmentCardProps {
  shipment: Shipment
  onClick: () => void
  loading?: boolean
}

export function ShipmentCard({ shipment, onClick, loading }: ShipmentCardProps) {
  if (loading) {
    return (
      <div className="bg-white rounded-2xl p-6 border" style={{ borderColor: '#EEE9DD', boxShadow: '0 8px 24px rgba(31,42,31,0.06)' }}>
        <div className="flex items-start justify-between mb-4">
          <div className="skeleton w-10 h-10 rounded-xl" />
          <div className="skeleton w-16 h-5 rounded-full" />
        </div>
        <div className="skeleton h-5 w-28 mb-1" />
        <div className="skeleton h-4 w-36 mb-4" />
        <div className="skeleton h-20 w-full rounded-xl mb-4" />
        <div className="skeleton h-2 w-full rounded-full" />
      </div>
    )
  }

  const { s } = { s: shipment }
  const ratio = shipment.remainingHours / shipment.totalHours
  const state = ratio > 0.5 ? 'fresh' : ratio > 0.2 ? 'caution' : 'critical'

  return (
    <div
      className="bg-white rounded-2xl p-6 border cursor-pointer transition-all duration-200 hover:-translate-y-1 group relative"
      style={{ borderColor: '#EEE9DD', boxShadow: '0 8px 24px rgba(31,42,31,0.06)' }}
      onClick={onClick}
      tabIndex={0}
      onKeyDown={e => e.key === 'Enter' && onClick()}
      role="button"
      aria-label={`Shipment ${shipment.code}`}
    >
      {shipment.isNew && (
        <span
          className="absolute top-4 right-4 text-xs font-semibold px-2 py-0.5 rounded-full animate-new-badge"
          style={{ background: '#F26B4F', color: 'white' }}
        >
          NEW
        </span>
      )}

      {/* Header */}
      <div className="flex items-start gap-3 mb-3">
        <div
          className="w-10 h-10 rounded-xl flex items-center justify-center text-xl shrink-0"
          style={{ background: '#EEF4EE' }}
        >
          {shipment.emoji}
        </div>
        <div className="flex-1 min-w-0">
          <div className="font-semibold text-sm truncate" style={{ color: '#1F2A1F' }}>
            {shipment.produce}
          </div>
          <div className="text-xs font-mono mt-0.5" style={{ color: '#6B7568' }}>
            #{shipment.code}
          </div>
        </div>
      </div>

      {/* Route */}
      <div className="flex items-center gap-2 mb-4">
        <span className="text-xs font-medium" style={{ color: '#6B7568' }}>{shipment.origin}</span>
        <span className="text-xs" style={{ color: '#D4CCBB' }}>→</span>
        <span className="text-xs font-medium" style={{ color: '#6B7568' }}>{shipment.destination}</span>
      </div>

      {/* Freshness Dial */}
      <div className="flex justify-center mb-4">
        <FreshnessDial
          totalHours={shipment.totalHours}
          remainingHours={shipment.remainingHours}
          size={130}
        />
      </div>

      {/* Temperature chip */}
      <div className="flex items-center justify-between mb-4">
        <span
          className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full font-medium"
          style={{
            background: shipment.tempStatus === 'high' ? '#FDE8E8' : '#E6F4EA',
            color: shipment.tempStatus === 'high' ? '#C0181D' : '#1F6B45',
          }}
        >
          🌡 {shipment.temperature}°C
          {shipment.tempStatus === 'high' && ' · High'}
        </span>

        {/* View details arrow */}
        <span
          className="text-xs font-medium flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"
          style={{ color: '#1F6B45' }}
        >
          Details
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M5 12h14M12 5l7 7-7 7"/>
          </svg>
        </span>
      </div>

      {/* Route progress bar */}
      <div>
        <div className="h-1.5 rounded-full overflow-hidden" style={{ background: '#EEE9DD' }}>
          <div
            className="h-full rounded-full transition-all"
            style={{ width: `${shipment.progress}%`, background: '#1F6B45' }}
          />
        </div>
        <div className="flex items-center justify-between mt-1.5">
          <span className="text-[10px]" style={{ color: '#6B7568' }}>
            {shipment.progress}% delivered
          </span>
          <span className="text-[10px]">🚚</span>
        </div>
      </div>
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { Navbar } from '../components/Navbar'
import { KPITile } from '../components/KPITile'
import { ShipmentCard } from '../components/ShipmentCard'
import { SHIPMENTS, ALERTS } from '../data/shipments'
import type { Shipment } from '../components/ShipmentCard'
import type { Alert } from '../data/shipments'

interface DistributorDashboardProps {
  onLogout: () => void
  onShipmentClick: (id: string) => void
}

export function DistributorDashboard({ onLogout, onShipmentClick }: DistributorDashboardProps) {
  const [loaded, setLoaded] = useState(false)
  const [alertsOpen, setAlertsOpen] = useState(true)
  const [activeTab, setActiveTab] = useState('dashboard')
  const [alerts, setAlerts] = useState<Alert[]>(ALERTS)

  useEffect(() => {
    const t = setTimeout(() => setLoaded(true), 800)
    return () => clearTimeout(t)
  }, [])

  const today = new Date().toLocaleDateString('en-IN', {
    weekday: 'long', day: 'numeric', month: 'long',
  })

  const atRisk = SHIPMENTS.filter(s => {
    const r = s.remainingHours / s.totalHours
    return r <= 0.2
  }).length

  return (
    <div className="min-h-screen" style={{ background: '#FAF7F0' }}>
      <Navbar
        role="distributor"
        activeTab={activeTab}
        onTabChange={setActiveTab}
        onLogout={onLogout}
      />

      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        {/* Greeting */}
        <div className="mb-8">
          <h1
            className="text-3xl font-medium mb-1"
            style={{ fontFamily: "'Fraunces', Georgia, serif", color: '#1F2A1F' }}
          >
            Good morning 👋
          </h1>
          <p className="text-sm" style={{ color: '#6B7568' }}>{today}</p>
        </div>

        {/* KPI row */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-10">
          <KPITile
            label="In transit"
            value={loaded ? String(SHIPMENTS.length) : '—'}
            trend="+2 today"
            trendUp
            icon="🚛"
            loading={!loaded}
          />
          <KPITile
            label="At risk"
            value={loaded ? String(atRisk) : '—'}
            trend="↑ 1"
            trendUp={false}
            icon="⚠️"
            loading={!loaded}
          />
          <KPITile
            label="Value saved (₹)"
            value={loaded ? '₹2.4Cr' : '—'}
            trend="+₹18L"
            trendUp
            icon="💰"
            loading={!loaded}
          />
          <KPITile
            label="Avg freshness left"
            value={loaded ? '46h' : '—'}
            trend="−3h"
            trendUp={false}
            icon="⏱"
            loading={!loaded}
          />
        </div>

        {/* Main content: shipments grid + alerts sidebar */}
        <div className="flex gap-6">
          {/* Shipments grid */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center justify-between mb-5">
              <h2
                className="text-xl font-medium"
                style={{ fontFamily: "'Fraunces', serif", color: '#1F2A1F' }}
              >
                Active Shipments
              </h2>
              <button
                className="text-sm font-medium px-4 py-1.5 rounded-lg border transition-colors hover:bg-white"
                style={{ color: '#1F6B45', borderColor: '#EEE9DD' }}
              >
                View all →
              </button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4">
              {SHIPMENTS.slice(0, 6).map(shipment =>
                loaded ? (
                  <ShipmentCard
                    key={shipment.id}
                    shipment={shipment}
                    onClick={() => onShipmentClick(shipment.id)}
                  />
                ) : (
                  <ShipmentCard
                    key={shipment.id}
                    shipment={shipment}
                    onClick={() => {}}
                    loading
                  />
                )
              )}
            </div>
          </div>

          {/* Alerts sidebar */}
          <div
            className="hidden lg:block w-72 shrink-0"
          >
            <div
              className="bg-white rounded-2xl border overflow-hidden sticky top-24"
              style={{ borderColor: '#EEE9DD', boxShadow: '0 8px 24px rgba(31,42,31,0.06)' }}
            >
              <div
                className="flex items-center justify-between px-5 py-4 border-b"
                style={{ borderColor: '#EEE9DD' }}
              >
                <div className="flex items-center gap-2">
                  <span className="text-sm font-semibold" style={{ color: '#1F2A1F' }}>
                    Live alerts
                  </span>
                  <span
                    className="text-xs px-1.5 py-0.5 rounded-full font-medium"
                    style={{ background: '#FDE8E8', color: '#C0181D' }}
                  >
                    {alerts.filter(a => a.dot === '#E5484D').length}
                  </span>
                </div>
                <button
                  onClick={() => setAlertsOpen(o => !o)}
                  className="text-xs"
                  style={{ color: '#6B7568' }}
                >
                  {alertsOpen ? '−' : '+'}
                </button>
              </div>

              {alertsOpen && (
                <div className="divide-y" style={{ borderColor: '#FAF7F0' }}>
                  {alerts.map(alert => (
                    <div
                      key={alert.id}
                      className="flex items-start gap-3 px-5 py-3.5 hover:bg-[#FAF7F0] transition-colors"
                    >
                      <span
                        className="w-2 h-2 rounded-full mt-1.5 shrink-0"
                        style={{ background: alert.dot }}
                      />
                      <div className="flex-1 min-w-0">
                        <p className="text-xs leading-snug line-clamp-2" style={{ color: '#1F2A1F' }}>
                          {alert.text}
                        </p>
                        <p className="text-[10px] mt-1" style={{ color: '#6B7568' }}>
                          {alert.time}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              )}

              <div className="px-5 py-3 border-t" style={{ borderColor: '#EEE9DD' }}>
                <button
                  className="text-xs font-medium"
                  style={{ color: '#1F6B45' }}
                >
                  View all alerts →
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

import React, { useState } from 'react'

interface LoginProps {
  onLogin: (role: 'distributor' | 'retailer') => void
}

export function Login({ onLogin }: LoginProps) {
  const [selectedRole, setSelectedRole] = useState<'distributor' | 'retailer' | null>(null)
  const [password, setPassword] = useState('')
  const [loading, setLoading] = useState(false)

  const handleContinue = () => {
    if (!selectedRole) return
    setLoading(true)
    setTimeout(() => {
      setLoading(false)
      onLogin(selectedRole)
    }, 700)
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row">
      {/* Left panel */}
      <div
        className="relative flex-1 flex flex-col justify-between p-10 md:p-14 overflow-hidden"
        style={{ background: 'linear-gradient(145deg, #2F6B45 0%, #1F5535 60%, #163D28 100%)' }}
      >
        {/* Leaf watermark */}
        <div
          className="absolute inset-0 leaf-pattern opacity-20 pointer-events-none"
          aria-hidden="true"
        />

        {/* Logo */}
        <div className="relative z-10">
          <div className="flex items-center gap-3">
            <div
              className="w-10 h-10 rounded-xl flex items-center justify-center text-white font-bold text-lg"
              style={{ background: 'rgba(255,255,255,0.15)', backdropFilter: 'blur(10px)', fontFamily: "'Fraunces', serif" }}
            >
              A
            </div>
            <span className="text-white text-xl font-semibold" style={{ fontFamily: "'Fraunces', serif" }}>
              AgroSense
            </span>
          </div>
        </div>

        {/* Hero text */}
        <div className="relative z-10 py-12 md:py-0">
          <h1
            className="text-4xl md:text-5xl font-medium leading-tight mb-5 text-white"
            style={{ fontFamily: "'Fraunces', Georgia, serif" }}
          >
            Know what's fresh.<br />
            Before it's<br />
            too late.
          </h1>
          <p className="text-base max-w-xs" style={{ color: 'rgba(255,255,255,0.7)', lineHeight: 1.6 }}>
            Real-time cold-chain tracking. Automatic markdown pricing. Zero waste.
          </p>

          {/* Stats row */}
          <div className="flex gap-8 mt-10">
            {[
              { value: '₹2.4Cr', label: 'saved this month' },
              { value: '98%', label: 'freshness accuracy' },
              { value: '340+', label: 'shipments live' },
            ].map(s => (
              <div key={s.label}>
                <div
                  className="text-2xl font-semibold text-white tabular-nums"
                  style={{ fontFamily: "'Fraunces', serif" }}
                >
                  {s.value}
                </div>
                <div className="text-xs mt-0.5" style={{ color: 'rgba(255,255,255,0.55)' }}>
                  {s.label}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Bottom tagline */}
        <div className="relative z-10">
          <p className="text-xs" style={{ color: 'rgba(255,255,255,0.4)' }}>
            Powering India's cold chain since 2023
          </p>
        </div>
      </div>

      {/* Right panel */}
      <div
        className="flex items-center justify-center p-8 md:p-12"
        style={{ background: '#FAF7F0', minWidth: 'min(480px, 100vw)' }}
      >
        <div className="w-full max-w-sm">
          <div className="mb-8">
            <h2
              className="text-2xl font-medium mb-2"
              style={{ fontFamily: "'Fraunces', Georgia, serif", color: '#1F2A1F' }}
            >
              Sign in
            </h2>
            <p className="text-sm" style={{ color: '#6B7568' }}>
              Choose your role to get started
            </p>
          </div>

          {/* Role cards */}
          <div className="grid grid-cols-2 gap-3 mb-6">
            {(['distributor', 'retailer'] as const).map(role => {
              const isSelected = selectedRole === role
              return (
                <button
                  key={role}
                  onClick={() => setSelectedRole(role)}
                  className="flex flex-col items-center gap-2.5 p-5 rounded-2xl border-2 transition-all duration-150 text-left"
                  style={{
                    borderColor: isSelected ? '#1F6B45' : '#EEE9DD',
                    background: isSelected ? '#EEF4EE' : 'white',
                    boxShadow: isSelected
                      ? '0 0 0 3px rgba(31,107,69,0.1)'
                      : '0 8px 24px rgba(31,42,31,0.06)',
                  }}
                >
                  <div
                    className="w-12 h-12 rounded-2xl flex items-center justify-center text-2xl transition-all"
                    style={{ background: isSelected ? '#D1E9DC' : '#F5F5F0' }}
                  >
                    {role === 'distributor' ? '🚛' : '🏪'}
                  </div>
                  <div>
                    <div
                      className="font-semibold text-sm capitalize"
                      style={{ color: isSelected ? '#1F6B45' : '#1F2A1F' }}
                    >
                      {role}
                    </div>
                    <div className="text-xs mt-0.5" style={{ color: '#6B7568' }}>
                      {role === 'distributor' ? 'Manage shipments' : 'Browse deals'}
                    </div>
                  </div>
                </button>
              )
            })}
          </div>

          {/* Password */}
          <div className="mb-5">
            <label
              className="block text-sm font-medium mb-1.5"
              htmlFor="password"
              style={{ color: '#1F2A1F' }}
            >
              Password
            </label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              placeholder="Enter your password"
              className="w-full px-4 py-3 rounded-xl border text-sm transition-all"
              style={{
                borderColor: '#EEE9DD',
                background: 'white',
                color: '#1F2A1F',
                outline: 'none',
              }}
              onFocus={e => (e.target.style.borderColor = '#1F6B45')}
              onBlur={e => (e.target.style.borderColor = '#EEE9DD')}
              onKeyDown={e => e.key === 'Enter' && handleContinue()}
            />
            <p className="text-xs mt-1.5" style={{ color: '#6B7568' }}>
              Hint: any password works in this demo
            </p>
          </div>

          {/* Continue button */}
          <button
            onClick={handleContinue}
            disabled={!selectedRole || loading}
            className="w-full py-3.5 rounded-xl font-semibold text-white text-sm transition-all duration-150 flex items-center justify-center gap-2"
            style={{
              background: selectedRole ? '#1F6B45' : '#D4CCBB',
              cursor: selectedRole ? 'pointer' : 'not-allowed',
              boxShadow: selectedRole ? '0 4px 14px rgba(31,107,69,0.3)' : 'none',
            }}
          >
            {loading ? (
              <>
                <svg className="animate-spin-slow w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>
                </svg>
                Signing in…
              </>
            ) : (
              'Continue →'
            )}
          </button>

          <p className="text-center text-xs mt-5" style={{ color: '#6B7568' }}>
            Protected by end-to-end encryption
          </p>
