interface RetailerMarketplaceProps {
  onLogout: () => void
}

type Filter = 'all' | 'flash' | 'under24' | 'vegetable' | 'fruit'

function freshnessColor(hours: number) {
  if (hours > 48) return { bg: '#E6F4EA', color: '#1F6B45' }
  if (hours > 12) return { bg: '#FDF1DA', color: '#B87A1A' }
  return { bg: '#FDE8E8', color: '#C0181D' }
}

interface ListingCardProps {
  listing: Listing
  onReserve: (listing: Listing) => void
}

function ListingCard({ listing, onReserve }: ListingCardProps) {
  const fc = freshnessColor(listing.freshnessHours)
  const formatHours = (h: number) => h >= 24 ? `${Math.floor(h / 24)}d ${h % 24}h` : `${h}h`

  return (
    <div
      className="bg-white rounded-2xl border overflow-hidden transition-all duration-200 hover:-translate-y-1 animate-scale-in"
      style={{ borderColor: '#EEE9DD', boxShadow: '0 8px 24px rgba(31,42,31,0.06)' }}
    >
      {/* Produce illustration area */}
      <div
