const FILTERS: { key: Filter; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'flash', label: '⚡ Flash sale' },
  { key: 'under24', label: '⏱ Under 24h' },
  { key: 'vegetable', label: '🥦 Vegetables' },
  { key: 'fruit', label: '🍊 Fruits' },
]

export function RetailerMarketplace({ onLogout }: RetailerMarketplaceProps) {
  const [activeFilter, setActiveFilter] = useState<Filter>('all')
  const [sortBy, setSortBy] = useState<'freshness' | 'price' | 'discount'>('discount')
  const [toast, setToast] = useState(false)
  const [reserving, setReserving] = useState<Listing | null>(null)
  const [qty, setQty] = useState(1)
  const [reserved, setReserved] = useState(false)
  const [listings, setListings] = useState(LISTINGS)

  // Show initial toast after mount
  useEffect(() => {
    const t = setTimeout(() => setToast(true), 1500)
    return () => clearTimeout(t)
  }, [])

  const filtered = listings.filter(l => {
    if (activeFilter === 'flash') return l.isFlashSale
    if (activeFilter === 'under24') return l.freshnessHours < 24
    if (activeFilter === 'vegetable') return l.category === 'vegetable'
    if (activeFilter === 'fruit') return l.category === 'fruit'
    return true
  }).sort((a, b) => {
    if (sortBy === 'freshness') return b.freshnessHours - a.freshnessHours
    if (sortBy === 'price') return a.discountedPrice - b.discountedPrice
    return b.discountPct - a.discountPct
  })

  const handleReserve = (listing: Listing) => {
    setReserving(listing)
    setQty(1)
    setReserved(false)
  }

  const handleConfirm = () => {
    setReserved(true)
  }

  const handleCloseDrawer = () => {
    setReserving(null)
    setReserved(false)
  }

  return (
    <div className="min-h-screen pb-16" style={{ background: '#FAF7F0' }}>
      <Navbar role="retailer" onLogout={onLogout} />

      {/* Toast */}
      <Toast
        visible={toast}
        message="Flash markdown: Tomatoes −45%"
        subtext="18h freshness left — act fast"
        onView={() => setToast(false)}
        onDismiss={() => setToast(false)}
      />

      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        {/* Page title */}
        <div className="mb-8">
