                <span style={{ color: '#1F2A1F' }}>₹{reserving.discountedPrice}</span>
              </div>
              <div className="flex justify-between text-sm mb-3">
                <span style={{ color: '#6B7568' }}>Quantity</span>
                <span style={{ color: '#1F2A1F' }}>× {qty}</span>
              </div>
              <div
                className="flex justify-between font-semibold pt-3 border-t"
                style={{ borderColor: '#EEE9DD' }}
              >
                <span style={{ color: '#1F2A1F' }}>Total</span>
                <span
                  className="text-lg tabular-nums"
                  style={{ fontFamily: "'Fraunces', serif", color: '#1F6B45' }}
                >
                  ₹{(reserving.discountedPrice * qty).toLocaleString('en-IN')}
                </span>
              </div>
              <p className="text-xs mt-2" style={{ color: '#6B7568' }}>
                Saved ₹{((reserving.originalPrice - reserving.discountedPrice) * qty).toLocaleString('en-IN')} vs original price
              </p>
            </div>

            {/* Confirm button */}
            <button
              onClick={handleConfirm}
              className="w-full py-3.5 rounded-xl font-semibold text-white text-sm transition-all hover:brightness-95"
              style={{
                background: '#1F6B45',
                boxShadow: '0 4px 14px rgba(31,107,69,0.3)',
