  onLogout: () => void
}

const NORMAL_DATA = [
  { h: 0, temp: 4.0 }, { h: 4, temp: 3.8 }, { h: 8, temp: 4.2 },
  { h: 12, temp: 4.5 }, { h: 16, temp: 4.1 }, { h: 20, temp: 3.9 },
  { h: 24, temp: 4.3 }, { h: 28, temp: 4.2 }, { h: 32, temp: 4.0 },
]

const SPIKE_DATA = [
  { h: 0, temp: 4.0 }, { h: 4, temp: 3.8 }, { h: 8, temp: 4.2 },
  { h: 12, temp: 4.5 }, { h: 14, temp: 7.2 }, { h: 16, temp: 12.4 },
  { h: 18, temp: 18.8 }, { h: 20, temp: 22.1 }, { h: 23, temp: 38.0 },
  { h: 26, temp: 31.2 }, { h: 30, temp: 18.4 }, { h: 32, temp: 9.1 },
]

const STEPPER_STEPS = [
  'Sending readings',
  'Calculating shelf life',
  'Updating price',
  'Alert sent',
]

type SimState = 'idle' | 'running' | 'done'

export function ShipmentDetail({ shipmentId, onBack, onLogout }: ShipmentDetailProps) {
  const shipment = SHIPMENTS.find(s => s.id === shipmentId) || SHIPMENTS[0]

  const [activeTab, setActiveTab] = useState<'temperature' | 'humidity' | 'why'>('temperature')
  const [simState, setSimState] = useState<SimState>('idle')
  const [simStep, setSimStep] = useState(-1)
  const [simPanelOpen, setSimPanelOpen] = useState(true)
  const [spiked, setSpiked] = useState(false)
  const [remainingHours, setRemainingHours] = useState(shipment.remainingHours)
  const [chartData, setChartData] = useState(NORMAL_DATA)
  const [price, setPrice] = useState({ original: 280, current: 280, discounted: false })
  const [newAlert, setNewAlert] = useState(false)
  const stepTimers = useRef<ReturnType<typeof setTimeout>[]>([])

  const clearTimers = () => {
    stepTimers.current.forEach(clearTimeout)
    stepTimers.current = []
  }

  const runSpike = () => {
    setSimState('running')
    setSimStep(0)

    const delays = [0, 900, 1800, 2700]
    delays.forEach((delay, i) => {
      const t = setTimeout(() => {
        setSimStep(i)
        if (i === 1) {
          setChartData(SPIKE_DATA)
          setSpiked(true)
          setRemainingHours(18)
        }
        if (i === 2) {
          setPrice({ original: 280, current: 154, discounted: true })
        }
        if (i === 3) {
          setNewAlert(true)
          setTimeout(() => {
            setSimState('done')
            setSimStep(-1)
          }, 600)
        }
      }, delay)
      stepTimers.current.push(t)
    })
  }

  const resetDemo = () => {
    clearTimers()
    setSimState('idle')
    setSimStep(-1)
    setSpiked(false)
    setRemainingHours(shipment.remainingHours)
    setChartData(NORMAL_DATA)
    setPrice({ original: 280, current: 280, discounted: false })
    setNewAlert(false)
  }

  useEffect(() => () => clearTimers(), [])

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (!active || !payload?.length) return null
    return (
      <div
        className="bg-white rounded-xl px-3 py-2 border text-xs"
        style={{ borderColor: '#EEE9DD', boxShadow: '0 4px 12px rgba(31,42,31,0.1)' }}
      >
        <p style={{ color: '#6B7568' }}>Hour {label}</p>
        <p style={{ color: payload[0].value > 8 ? '#E5484D' : '#2F9E5B', fontWeight: 600 }}>
          {payload[0].value}°C
        </p>
      </div>
    )
  }

  const status = (() => {
    const r = remainingHours / shipment.totalHours
    if (r > 0.5) return { label: 'In transit', bg: '#E6F4EA', color: '#1F6B45' }
    if (r > 0.2) return { label: 'At risk', bg: '#FDF1DA', color: '#B87A1A' }
    return { label: 'Critical', bg: '#FDE8E8', color: '#C0181D' }
  })()

  return (
    <div className="min-h-screen pb-32" style={{ background: '#FAF7F0' }}>
      <Navbar role="distributor" onLogout={onLogout} />

      <div className="max-w-6xl mx-auto px-4 sm:px-6 py-8">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 mb-6 text-sm" style={{ color: '#6B7568' }}>
          <button
            onClick={onBack}
            className="hover:text-[#1F6B45] transition-colors flex items-center gap-1"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M19 12H5M12 19l-7-7 7-7"/>
            </svg>
            Dashboard
          </button>
          <span style={{ color: '#D4CCBB' }}>›</span>
          <span style={{ color: '#1F2A1F' }}>#{shipment.code}</span>
        </div>

        {/* Title row */}
        <div className="flex items-center gap-4 mb-8 flex-wrap">
          <div
            className="w-12 h-12 rounded-2xl flex items-center justify-center text-2xl"
            style={{ background: '#EEF4EE' }}
          >
            {shipment.emoji}
          </div>
          <div>
            <h1
              className="text-2xl font-medium"
              style={{ fontFamily: "'Fraunces', Georgia, serif", color: '#1F2A1F' }}
            >
              {shipment.produce}
            </h1>
            <p className="text-sm" style={{ color: '#6B7568' }}>
              {shipment.origin} → {shipment.destination}
            </p>
          </div>
          <span
            className="px-3 py-1 rounded-full text-sm font-medium ml-auto"
            style={{ background: status.bg, color: status.color }}
          >
            {status.label}
          </span>
        </div>

