/**
 * app/api/demo/reset/route.ts
 * POST /api/demo/reset
 * Distributor only — resets the demo shipment AGS-101 to its initial state.
 * Telemetry stays append-only (trigger prevents DELETE); we insert a reset event instead.
 */

import { NextRequest } from "next/server";
import { requireRole } from "@/lib/auth";
import { db } from "@/lib/db";

const DEMO_CODE = "AGS-101";
const DEMO_INITIAL_LIFE = 120;
const DEMO_BASE_PRICE = 40;

export async function POST(req: NextRequest) {
  // ── 1. Require distributor ────────────────────────────────────────────
  const authResult = await requireRole("distributor");
  if (authResult instanceof Response) return authResult;

  // ── 2. Find demo shipment ─────────────────────────────────────────────
  const { data: shipment, error } = await db
    .from("shipments")
    .select("id")
    .eq("code", DEMO_CODE)
    .single();

  if (error || !shipment) {
    return Response.json({ error: "Demo shipment not found" }, { status: 404 });
  }

  const shipmentId = shipment.id;

  // ── 3. Reset shipment to initial state ────────────────────────────────
  const { error: resetErr } = await db
    .from("shipments")
    .update({
      remaining_life_hours: DEMO_INITIAL_LIFE,
      current_price_per_kg: DEMO_BASE_PRICE,
      status: "in_transit",
      last_reading_at: null,
    })
    .eq("id", shipmentId);

  if (resetErr) {
    return Response.json({ error: "Reset failed: " + resetErr.message }, { status: 500 });
  }

  // ── 4. Deactivate all listings for this shipment ───────────────────────
  await db
    .from("listings")
    .update({ active: false })
    .eq("shipment_id", shipmentId);

  // ── 5. Insert reset event as a telemetry annotation (append-only safe) ─
  // We record a "comment" row with burn_rate=0 to mark the reset in the timeline
  await db.from("alerts").insert({
    shipment_id: shipmentId,
    severity: "info",
    message: `Demo reset: AGS-101 returned to ${DEMO_INITIAL_LIFE}h / ₹${DEMO_BASE_PRICE}/kg at ${new Date().toISOString()}`,
  });

  // Telemetry rows remain — append-only integrity preserved.
  // The pipeline re-accumulates from the new last_reading_at=null baseline.

  return Response.json({
    ok: true,
    remaining_life_hours: DEMO_INITIAL_LIFE,
    current_price_per_kg: DEMO_BASE_PRICE,
    status: "in_transit",
  });
}

/**
 * app/api/listings/route.ts
 * GET /api/listings?since=<ISO timestamp> — active listings for marketplace (retailer)
 * The ?since param enables efficient polling: only fetch listings newer than last check.
 */

import { NextRequest } from "next/server";
import { requireRole } from "@/lib/auth";
import { db } from "@/lib/db";

export async function GET(req: NextRequest) {
  const authResult = await requireRole("retailer");
  if (authResult instanceof Response) return authResult;

  const since = req.nextUrl.searchParams.get("since");

  let query = db
    .from("listings")
    .select("*, shipments(code, produce_type, qty_kg, origin, destination), reservations(qty_kg)")
    .eq("active", true)
    .order("created_at", { ascending: false })
    .limit(50);

  // If ?since is provided, only return listings newer than that timestamp
  if (since) {
    query = query.gt("created_at", since);
  }

  const { data, error } = await query;

  if (error) {
    return Response.json({ error: "Failed to fetch listings" }, { status: 500 });
  }

  // Compute available_kg based on reservations sum
  const enhanced = data?.map((l: any) => {
    const reservedTotal = Array.isArray(l.reservations) 
      ? l.reservations.reduce((sum: number, r: any) => sum + (r.qty_kg || 0), 0)
      : 0;

    // ensure available_kg is never negative; defaults to shipment qty_kg
    const available_kg = Math.max(0, (l.shipments?.qty_kg || 0) - reservedTotal);

    delete l.reservations; // clean up payload
    return {
      ...l,
      available_kg
    };
  });

  return Response.json({
    listings: enhanced ?? [],
    fetched_at: new Date().toISOString(),
  });
}

import { NextRequest } from "next/server";
import { requireRole } from "@/lib/auth";
import { db } from "@/lib/db";
import { z } from "zod";

const reserveSchema = z.object({
  listing_id: z.string().uuid(),
  qty_kg: z.number().int().positive()
});

export async function POST(req: NextRequest) {
  const authResult = await requireRole("retailer");
  if (authResult instanceof Response) return authResult;

  try {
    const json = await req.json();
    const { listing_id, qty_kg } = reserveSchema.parse(json);

    // Fetch listing for prices and active status
    const { data: listing, error: listingErr } = await db
      .from("listings")
      .select("*, shipments(qty_kg)")
      .eq("id", listing_id)
      .eq("active", true)
      .single();

    if (listingErr || !listing) {
      return Response.json({ error: "Active listing not found" }, { status: 404 });
    }

    // Verify availability
    const { data: reservations } = await db
      .from("reservations")
      .select("qty_kg")
      .eq("listing_id", listing_id);

    const reservedTotal = reservations?.reduce((sum, r) => sum + r.qty_kg, 0) ?? 0;
    const shipmentQty = Array.isArray(listing.shipments) ? listing.shipments[0]?.qty_kg : (listing.shipments as any)?.qty_kg;
    const available_kg = Math.max(0, (shipmentQty || 0) - reservedTotal);

    if (qty_kg > available_kg) {
      return Response.json({ error: "Requested quantity exceeds available stock" }, { status: 400 });
    }

    // Calculate total on server using trusted listing price
    const total_price = qty_kg * listing.discounted_price;

    const { data: reservation, error: reserveErr } = await db
      .from("reservations")
      .insert({
        listing_id,
        qty_kg,
        total_price
      })
      .select()
      .single();

    if (reserveErr) throw new Error("Reservation insert failed: " + reserveErr.message);

    return Response.json({ success: true, reservation });
  } catch (e: any) {
    console.error("[api] Reservation Error:", e);
    return Response.json({ error: e.message || "Invalid request" }, { status: 400 });
  }
}

import { requireRole } from "@/lib/auth";
import { db } from "@/lib/db";
import { getProfile } from "@/lib/produce";

export async function GET() {
  const authResult = await requireRole("distributor");
  if (authResult instanceof Response) return authResult;

  const { data, error } = await db
    .from("shipments")
    .select(`
      *,
      telemetry ( temp_c, recorded_at )
    `)
    .order("created_at", { ascending: false });

  if (error) {
    return Response.json({ error: "Failed to fetch shipments" }, { status: 500 });
  }

  // Calculate read-only UI fields
  const enhanced = data.map((s: any) => {
    const profile = getProfile(s.produce_type);

    // Sort telemetry to get the latest reading
    const sortedTele = Array.isArray(s.telemetry) 
      ? s.telemetry.sort((a: any, b: any) => new Date(b.recorded_at).getTime() - new Date(a.recorded_at).getTime())
      : [];

    const latest_temp_c = sortedTele.length > 0 ? sortedTele[0].temp_c : null;

    // Elapsed time calculation in real hours based on first and last telemetry, or created_at
    let elapsedRealH = 0;
    if (sortedTele.length > 1) {
      const first = new Date(sortedTele[sortedTele.length - 1].recorded_at).getTime();
      const last = new Date(sortedTele[0].recorded_at).getTime();
      elapsedRealH = (last - first) / 3600000;
    } else {
      const created = new Date(s.created_at).getTime();
      elapsedRealH = (Date.now() - created) / 3600000;
    }

    // Progress %
    const etaH = s.eta_hours || 1;
    const progressPct = Math.min(100, Math.max(0, Math.round((elapsedRealH / etaH) * 100)));

    // Ensure we don't pass massive arrays of telemetry down to the grid list API response
    // (We only used it to get latest_temp_c)
    delete s.telemetry;

    return {
      ...s,
      latest_temp_c,
      ideal_temp_range: [profile.tRef - 2, profile.tRef + 2], // Arbitrary +/- 2 ideal band
      transit_progress_pct: progressPct
    };
  });

  return Response.json({ shipments: enhanced });
}

"use client";
import React, { useState, useEffect, useRef } from 'react'
import { Navbar } from '@/components/Navbar'
import { Toast } from '@/components/Toast'
import { Drawer } from '@/components/Drawer'
import { usePolling } from '@/hooks/usePolling'
import { mapListingRows } from '@/lib/mappers'
import type { UIListing } from '@/types/ui'

type Filter = 'all' | 'flash' | 'under24' | 'vegetable' | 'fruit'

function freshnessColor(hours: number) {
  if (hours > 48) return { bg: 'var(--color-fresh-bg)', color: 'var(--color-leaf)' }
  if (hours > 12) return { bg: 'var(--color-caution-bg)', color: '#B87A1A' }
  return { bg: 'var(--color-critical-bg)', color: '#C0181D' }
}

interface ListingCardProps {
  listing: UIListing
  onReserve: (listing: UIListing) => void
}

function ListingCard({ listing, onReserve }: ListingCardProps) {
  const fc = freshnessColor(listing.freshnessHours)
  const formatHours = (h: number) => h >= 24 ? `\${Math.floor(h / 24)}d \${h % 24}h` : `\${Math.floor(h)}h`

  return (
    <div
      className="bg-card rounded-2xl border border-border overflow-hidden transition-all duration-200 hover:-translate-y-1 animate-scale-in card-shadow"
    >
      <div
        className="relative flex items-center justify-center py-8"
        style={{ background: 'linear-gradient(145deg, #FAF7F0 0%, #F0EDE6 100%)' }}
      >
        <span className="text-5xl">{listing.emoji}</span>

        {listing.discountPct > 0 && (
          <div
            className="absolute top-3 right-3 px-2 py-0.5 rounded-full text-xs font-bold"
            style={{ background: 'var(--color-tomato)', color: 'white' }}
          >
            −{listing.discountPct}%
          </div>
        )}

        {listing.isNew && (
          <div
            className="absolute top-3 left-3 px-2 py-0.5 rounded-full text-xs font-bold animate-new-badge bg-leaf text-white"
          >
            NEW
          </div>
        )}

        {listing.isFlashSale && (
          <div
            className="absolute bottom-3 left-1/2 -translate-x-1/2 px-2.5 py-0.5 rounded-full text-[10px] font-semibold bg-caution-bg text-caution"
          >
            ⚡ Flash sale
          </div>
        )}
      </div>

      <div className="p-5">
        <div className="flex items-start justify-between mb-1">
          <div>
            <h3 className="font-semibold text-sm leading-tight text-green-black">
              {listing.produce}
            </h3>
            <p className="text-xs mt-0.5 text-muted">{listing.quantityStr}</p>
          </div>
          <span
            className="text-[10px] px-2 py-0.5 rounded-full font-medium shrink-0 ml-2"
            style={{ background: fc.bg, color: fc.color }}
          >
            {formatHours(listing.freshnessHours)} left
          </span>
        </div>

        <div className="flex items-baseline gap-2 mt-3 mb-2">
          <span
            className="text-2xl font-semibold tabular-nums font-serif text-green-black"
          >
            ₹{listing.discountedPrice}
          </span>
          {listing.discountPct > 0 && (
            <span className="text-sm line-through text-muted">
              ₹{listing.originalPrice}
            </span>
          )}
        </div>

        <p className="text-xs mb-4 leading-relaxed line-clamp-2 text-muted">
          {listing.aiLine}
        </p>

        <button
          onClick={() => onReserve(listing)}
          disabled={listing.availableKg <= 0}
          className="w-full py-2.5 rounded-xl text-sm font-semibold text-white transition-all duration-150 hover:brightness-95 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed bg-leaf card-shadow"
        >
          {listing.availableKg <= 0 ? 'Sold Out' : 'Reserve'}
        </button>
      </div>
    </div>
  )
}

const FILTERS: { key: Filter; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'flash', label: '⚡ Flash sale' },
  { key: 'under24', label: '⏱ Under 24h' },
  { key: 'vegetable', label: '🥦 Vegetables' },
  { key: 'fruit', label: '🍊 Fruits' },
]

export default function RetailerMarketplace() {
  const [activeFilter, setActiveFilter] = useState<Filter>('all')
  const [sortBy, setSortBy] = useState<'freshness' | 'price' | 'discount'>('discount')

  const [toast, setToast] = useState<{ id: string, produce: string, discount: number, remainingHours: number } | null>(null)
  const knownListingIds = useRef<Set<string>>(new Set())

  const [reserving, setReserving] = useState<UIListing | null>(null)
  const [qty, setQty] = useState(10) // 10kg default
  const [reserveStatus, setReserveStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle')
  const [reserveError, setReserveError] = useState('')

  const { data: listingData, loading } = usePolling<{ listings: any[] }>('/api/listings', { intervalMs: 3000 })

  const rawListings = listingData?.listings ?? []
  const listings: UIListing[] = rawListings.map(row => mapListingRows(row))

  useEffect(() => {
    // Check for *new* flash sales to show a toast
    if (listings.length > 0) {
      if (knownListingIds.current.size === 0) {
        // Initial load, just track all so we don't spam toasts on mount
        listings.forEach(l => knownListingIds.current.add(l.id))
      } else {
        const newFlashSales = listings.filter(l => !knownListingIds.current.has(l.id) && l.isFlashSale)
        if (newFlashSales.length > 0) {
          const l = newFlashSales[0]
          setToast({ id: l.id, produce: l.produce, discount: l.discountPct, remainingHours: l.freshnessHours })
        }
        // Track everything new so we don't toast twice
        listings.forEach(l => knownListingIds.current.add(l.id))
      }
    }
  }, [listings])

  const filtered = listings.filter(l => {
    if (activeFilter === 'flash') return l.isFlashSale
    if (activeFilter === 'under24') return l.freshnessHours < 24
    if (activeFilter === 'vegetable') return l.category === 'vegetable'
    if (activeFilter === 'fruit') return l.category === 'fruit'
    return true
  }).sort((a, b) => {
    if (sortBy === 'freshness') return a.freshnessHours - b.freshnessHours
    if (sortBy === 'price') return a.discountedPrice - b.discountedPrice
    return b.discountPct - a.discountPct
  })

  const handleReserve = (listing: UIListing) => {
    setReserving(listing)
    setQty(Math.min(50, listing.availableKg))
    setReserveStatus('idle')
    setReserveError('')
  }

  const handleConfirm = async () => {
    if (!reserving) return
    setReserveStatus('loading')
    setReserveError('')

    try {
      const res = await fetch('/api/reservations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ listing_id: reserving.id, qty_kg: qty })
      })
      if (!res.ok) {
        const d = await res.json()
        throw new Error(d.error || 'Failed to reserve')
      }
      setReserveStatus('success')
    } catch (e: any) {
      setReserveStatus('error')
      setReserveError(e.message)
    }
  }

  const handleCloseDrawer = () => {
    setReserving(null)
    setReserveStatus('idle')
  }

  return (
    <div className="min-h-screen pb-16 bg-cream font-sans">
      <Navbar role="retailer" />

      {/* Smart Toast */}
      <Toast
        visible={!!toast}
        message={toast ? `Flash markdown: \${toast.produce} −\${toast.discount}%` : ''}
        subtext={toast ? `\${Math.floor(toast.remainingHours)}h freshness left — act fast` : ''}
        onView={() => setToast(null)}
        onDismiss={() => setToast(null)}
      />

      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        <div className="mb-8">
          <h1
            className="text-3xl font-medium mb-1.5 font-serif text-green-black"
          >
            Fresh deals near you
          </h1>
          <p className="text-sm text-muted">
            AI-priced perishables — reserve before they're gone
          </p>
        </div>

        {/* Filters + sort */}
        <div className="flex flex-wrap items-center gap-3 mb-8">
          <div className="flex flex-wrap gap-2">
            {FILTERS.map(f => (
              <button
                key={f.key}
                onClick={() => setActiveFilter(f.key)}
                className="px-3.5 py-1.5 rounded-full text-sm font-medium transition-all duration-150"
                style={{
                  background: activeFilter === f.key ? 'var(--color-leaf)' : 'white',
                  color: activeFilter === f.key ? 'white' : 'var(--color-muted)',
                  border: `1px solid \${activeFilter === f.key ? 'var(--color-leaf)' : 'var(--color-border)'}`,
                }}
              >
                {f.label}
              </button>
            ))}
          </div>

          <div className="ml-auto">
            <select
              value={sortBy}
              onChange={e => setSortBy(e.target.value as any)}
              className="text-sm border border-border rounded-xl px-3 py-2 bg-white text-green-black outline-none"
            >
              <option value="discount">Sort: Biggest discount</option>
              <option value="freshness">Sort: Freshest first</option>
              <option value="price">Sort: Lowest price</option>
            </select>
          </div>
        </div>

        {/* Listing grid */}
        {loading && filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-24 gap-3 text-muted">Loading deals...</div>
        ) : filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-24 gap-3">
            <span className="text-4xl">🌿</span>
            <p className="font-semibold text-green-black">No listings match this filter</p>
            <button
              onClick={() => setActiveFilter('all')}
              className="text-sm text-leaf"
            >
              Clear filter
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
            {filtered.map(listing => (
              <ListingCard
                key={listing.id}
                listing={listing}
                onReserve={handleReserve}
              />
            ))}
          </div>
        )}
      </div>

      {/* Reserve drawer */}
      <Drawer
        open={!!reserving}
        onClose={handleCloseDrawer}
        title={reserveStatus === 'success' ? 'Reserved!' : `Reserve \${reserving?.produce || ''}`}
      >
        {reserving && reserveStatus !== 'success' && (
          <div className="flex flex-col h-full">
            <div
              className="flex items-center gap-4 p-4 rounded-2xl mb-6 bg-cream border border-border"
            >
              <span className="text-3xl">{reserving.emoji}</span>
              <div>
                <p className="font-semibold text-green-black">{reserving.produce}</p>
                <p className="text-xs text-muted">{reserving.availableKg}kg available</p>
              </div>
            </div>

            <div className="mb-6">
              <label className="block text-sm font-medium mb-3 text-green-black">
                Quantity (kg)
              </label>
              <div className="flex items-center gap-4">
                <button
                  onClick={() => setQty(q => Math.max(10, q - 10))}
                  className="w-10 h-10 rounded-xl border border-border flex items-center justify-center text-lg font-semibold transition-colors hover:bg-cream text-green-black"
                >
                  −
                </button>
                <span
                  className="text-2xl font-semibold tabular-nums w-14 text-center font-serif text-green-black"
                >
                  {qty}
                </span>
                <button
                  onClick={() => setQty(q => Math.min(reserving.availableKg, q + 10))}
                  className="w-10 h-10 rounded-xl border border-border flex items-center justify-center text-lg font-semibold transition-colors hover:bg-cream text-green-black"
                >
                  +
                </button>
              </div>
            </div>

            <div
              className="rounded-2xl p-4 mb-6 bg-cream border border-border"
            >
              <div className="flex justify-between text-sm mb-2">
                <span className="text-muted">Unit price (per kg)</span>
                <span className="text-green-black">₹{reserving.discountedPrice}</span>
              </div>
              <div className="flex justify-between text-sm mb-3">
                <span className="text-muted">Quantity</span>
                <span className="text-green-black">× {qty}</span>
              </div>
              <div
                className="flex justify-between font-semibold pt-3 border-t border-border"
              >
                <span className="text-green-black">Total</span>
                <span
                  className="text-lg tabular-nums font-serif text-leaf"
                >
                  ₹{(reserving.discountedPrice * qty).toLocaleString('en-IN')}
                </span>
              </div>
              {reserving.discountPct > 0 && (
                <p className="text-xs mt-2 text-muted">
                  Saved ₹{((reserving.originalPrice - reserving.discountedPrice) * qty).toLocaleString('en-IN')} vs original price
                </p>
              )}
            </div>

            {reserveError && (
              <p className="text-critical text-sm mb-4 font-semibold text-center">{reserveError}</p>
            )}

            <button
              onClick={handleConfirm}
              disabled={reserveStatus === 'loading'}
              className="w-full py-3.5 rounded-xl font-semibold text-white text-sm transition-all hover:brightness-95 bg-leaf card-shadow disabled:opacity-50"
            >
              {reserveStatus === 'loading' ? 'Processing...' : 'Confirm reservation →'}
            </button>
          </div>
        )}

        {reserving && reserveStatus === 'success' && (
          <div className="flex flex-col items-center justify-center h-full gap-5 text-center">
            <div
              className="w-20 h-20 rounded-full flex items-center justify-center text-3xl animate-scale-in bg-fresh-bg text-leaf"
            >
              ✓
            </div>
            <div>
              <h3
                className="text-2xl font-medium mb-2 font-serif text-green-black"
              >
                Reserved!
              </h3>
              <p className="text-sm text-muted">
                {qty}kg of {reserving.produce} reserved successfully.
                <br />
                Collect within {reserving.freshnessHours > 24 ? `\${Math.floor(reserving.freshnessHours / 24)} days` : `\${Math.floor(reserving.freshnessHours)} hours`}.
              </p>
            </div>
            <div
              className="w-full rounded-2xl p-4 bg-cream border border-border"
            >
              <div className="flex justify-between text-sm">
                <span className="text-muted">Order total</span>
                <span
                  className="font-semibold tabular-nums font-serif text-leaf"
                >
                  ₹{(reserving.discountedPrice * qty).toLocaleString('en-IN')}
                </span>
              </div>
            </div>
            <button
              onClick={handleCloseDrawer}
              className="w-full py-3 rounded-xl font-medium border border-border transition-colors hover:bg-cream text-muted"
            >
              Continue browsing
            </button>
          </div>
        )}
      </Drawer>
    </div>
  )
}

"use client";
import React, { useState, useEffect, useRef, use } from 'react'
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip,
  ReferenceLine, ReferenceArea, ResponsiveContainer,
} from 'recharts'
import { Navbar } from '@/components/Navbar'
import { FreshnessDial, formatTime } from '@/components/FreshnessDial'
import { getProduceUI } from '@/lib/produce-ui'
import { useRouter } from 'next/navigation'

const STEPPER_STEPS = [
  'Sending readings',
  'Calculating shelf life',
  'Updating price',
  'Alert sent',
]

type SimState = 'idle' | 'running' | 'done' | 'error'

export default function ShipmentDetail({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = use(params)
  const shipmentId = resolvedParams.id
  const router = useRouter()

  const [simState, setSimState] = useState<SimState>('idle')
  const [simStep, setSimStep] = useState(-1)
  const [simPanelOpen, setSimPanelOpen] = useState(true)
  const [simError, setSimError] = useState('')

  const [activeTab, setActiveTab] = useState<'temperature' | 'humidity' | 'why'>('temperature')
  const [loading, setLoading] = useState(true)
  const [data, setData] = useState<any>(null)

  const fetchDetail = async () => {
    try {
      const res = await fetch(`/api/shipments/${shipmentId}`)
      if (!res.ok) throw new Error("Failed to load")
      const json = await res.json()
      setData(json)
    } catch (e) {
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchDetail()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [shipmentId])


  const runSpike = async () => {
    setSimState('running')
    setSimStep(0)
    setSimError('')
    try {
      // step 1: Sending readings
      const res = await fetch('/api/simulate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ shipment_id: shipmentId, scenario: 'spike' })
      })

      setSimStep(1) // calculating shelf life
      if (!res.ok) throw new Error('Simulation API failed')

      setTimeout(() => setSimStep(2), 500) // Updating price
      setTimeout(() => setSimStep(3), 1000) // Alert sent
      setTimeout(() => {
        setSimState('done')
        setSimStep(-1)
        fetchDetail() // reload to show new data
      }, 1500)

    } catch (e: any) {
      setSimState('error')
      setSimError(e.message)
    }
  }

  const runNormal = async () => {
    setSimState('running')
    setSimStep(0)
    setSimError('')
    try {
      const res = await fetch('/api/simulate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ shipment_id: shipmentId, scenario: 'normal' })
      })

      setSimStep(1)
      if (!res.ok) throw new Error('Simulation API failed')

      setTimeout(() => setSimStep(2), 500)
      setTimeout(() => setSimStep(3), 1000)
      setTimeout(() => {
        setSimState('done')
        setSimStep(-1)
        fetchDetail()
      }, 1500)

    } catch (e: any) {
      setSimState('error')
      setSimError(e.message)
    }
  }

  const resetDemo = async () => {
    setSimState('running')
    setSimStep(0)
    try {
      await fetch('/api/demo/reset', { method: 'POST' })
      setSimState('idle')
      setSimStep(-1)
      fetchDetail()
    } catch (e) {
      setSimState('error')
      setSimError("Failed to reset demo")
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen pb-32 bg-cream font-sans">
        <Navbar role="distributor" />
        <div className="flex items-center justify-center p-20">Loading...</div>
      </div>
    )
  }

  if (!data || !data.shipment) {
    return (
      <div className="min-h-screen pb-32 bg-cream font-sans">
        <Navbar role="distributor" />
        <div className="flex flex-col items-center justify-center p-20 gap-4">
          <p>Shipment not found</p>
          <button onClick={() => router.push('/dashboard')} className="text-leaf">Back to Dashboard</button>
        </div>
      </div>
    )
  }

  const s = data.shipment
  const ui = getProduceUI(s.produce_type)
  const isSpiked = s.status === 'at_risk' || s.status === 'critical'

  // Transform telemetry for chart
  let startH = 0
  if (data.telemetry.length > 0) {
    startH = new Date(data.telemetry[0].recorded_at).getTime()
  }

  const chartData = data.telemetry.map((t: any) => {
    const timeDiffMs = new Date(t.recorded_at).getTime() - startH
    return {
      h: Math.round(timeDiffMs / 3600000), // convert ms to hours relative to first record
      temp: t.temp_c,
      humidity: t.humidity_pct
    }
  })

  // Prepare price / discount details
  const hasListing = data.active_listing && data.active_listing.discount_pct > 0
  const originalPrice = data.active_listing?.original_price ?? s.base_price_per_kg
  const currentPrice = data.active_listing?.discounted_price ?? s.current_price_per_kg

  // Model breakdown timeline
  const breakdown = data.breakdown || []

  // Ensure AI insight has fallback
  let insightRaw = data.active_listing?.reason || "Shipment is progressing normally. Estimated arrival at destination with freshness remaining within optimal range.";
  let insightText = insightRaw.replace(/^AI: /, '').trim();

  // If no listing (fresh), provide template text
  if (!data.active_listing && !isSpiked) {
    const rem = formatTime(s.remaining_life_hours)
    insightText = `Shipment is progressing normally. ETA and freshness timeline align with initial projections (Freshness left: \${rem}).`
  }

  const statusObj = (() => {
    const r = s.remaining_life_hours / s.initial_life_hours
    if (r > 0.5) return { label: 'In transit', bg: 'var(--color-fresh-bg)', color: 'var(--color-leaf)' }
    if (r > 0.2) return { label: 'At risk', bg: 'var(--color-caution-bg)', color: '#B87A1A' }
    return { label: 'Critical', bg: 'var(--color-critical-bg)', color: '#C0181D' }
  })()

  // Chart Tooltip
  const CustomTooltip = ({ active, payload, label }: any) => {
    if (!active || !payload?.length) return null

    // Check if the individual point is high temp based on ideal range
    const isHigh = s.ideal_temp_range && payload[0].value > s.ideal_temp_range[1]

    return (
      <div
        className="bg-card rounded-xl px-3 py-2 border border-border text-xs card-shadow"
      >
        <p className="text-muted">Hour {label}</p>
        <p style={{ color: isHigh ? 'var(--color-critical)' : 'var(--color-fresh)', fontWeight: 600 }}>
          {payload[0].value}°C
        </p>
      </div>
    )
  }

  return (
    <div className="min-h-screen pb-32 bg-cream font-sans">
      <Navbar role="distributor" />

      <div className="max-w-6xl mx-auto px-4 sm:px-6 py-8">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 mb-6 text-sm text-muted">
          <button
            onClick={() => router.push('/dashboard')}
            className="hover:text-leaf transition-colors flex items-center gap-1"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M19 12H5M12 19l-7-7 7-7"/>
            </svg>
            Dashboard
          </button>
          <span style={{ color: '#D4CCBB' }}>›</span>
          <span className="text-green-black">#{s.code}</span>
        </div>

        {/* Title row */}
        <div className="flex items-center gap-4 mb-8 flex-wrap">
          <div
            className="w-12 h-12 rounded-2xl flex items-center justify-center text-2xl bg-sage-light"
          >
            {ui.emoji}
          </div>
          <div>
            <h1
              className="text-2xl font-medium font-serif text-green-black"
            >
              {ui.label}
            </h1>
            <p className="text-sm text-muted">
              {s.origin} → {s.destination}
            </p>
          </div>
          <span
            className="px-3 py-1 rounded-full text-sm font-medium ml-auto"
            style={{ background: statusObj.bg, color: statusObj.color }}
          >
            {statusObj.label}
          </span>
        </div>

        {/* Hero row: Dial + Price card */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          {/* Freshness Dial */}
          <div
            className="bg-card rounded-2xl p-8 border border-border flex flex-col items-center card-shadow"
          >
            <FreshnessDial
              totalHours={s.initial_life_hours}
              remainingHours={s.remaining_life_hours}
              size={200}
              animate
            />
          </div>

          {/* Price card */}
          <div
            className="bg-card rounded-2xl p-8 border border-border flex flex-col justify-center card-shadow"
          >
            <p className="text-sm font-medium mb-2 text-muted">
              Current market price
            </p>
            <div className="flex items-end gap-3 mb-3">
              <span
                className="text-4xl font-semibold tabular-nums font-serif text-green-black"
              >
                ₹{currentPrice}
              </span>
              {hasListing && (
                <span
                  className="text-xl relative animate-strike text-muted"
                >
                  ₹{originalPrice}
                </span>
              )}
            </div>

            {hasListing ? (
              <div className="flex items-center gap-2">
                <span
                  className="px-2.5 py-1 rounded-full text-sm font-semibold text-white tracking-wide"
                  style={{ background: 'var(--color-tomato)' }}
                >
                  −{data.active_listing.discount_pct}% markdown
                </span>
                <span className="text-xs text-muted">
                  auto-triggered by AI
                </span>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <span
                  className="px-2.5 py-1 rounded-full text-xs font-medium bg-fresh-bg text-leaf"
                >
                  Base price active
                </span>
              </div>
            )}

            <div className="mt-5 p-3 rounded-xl bg-cream border border-border">
              <div className="text-xs font-medium mb-1 text-muted">
                Markdown tiers
              </div>
              {[
                { range: '> 50% freshness', tier: 'Base price', active: s.current_tier === 'none' || !hasListing },
                { range: '20–50% freshness', tier: '−25% markdown', active: s.current_tier === 'tier25' },
                { range: '< 20% freshness', tier: '−45% markdown', active: s.current_tier === 'tier45' },
              ].map((t, idx) => (
                <div
                  key={idx}
                  className="flex items-center justify-between py-1"
                >
                  <span className="text-xs" style={{ color: t.active ? 'var(--color-green-black)' : 'var(--color-muted)' }}>
                    {t.range}
                  </span>
                  <span
                    className="text-xs font-medium"
                    style={{ color: t.active ? 'var(--color-tomato)' : 'var(--color-muted)' }}
                  >
                    {t.tier}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div
          className="bg-card rounded-2xl border border-border overflow-hidden mb-6 card-shadow"
        >
          {/* Tab switcher */}
          <div className="flex border-b border-border">
            {(['temperature', 'humidity', 'why'] as const).map(tab => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className="px-6 py-4 text-sm font-medium transition-colors relative"
                style={{
                  color: activeTab === tab ? 'var(--color-leaf)' : 'var(--color-muted)',
                  borderBottom: activeTab === tab ? '2px solid var(--color-leaf)' : '2px solid transparent',
                  background: 'white',
                }}
              >
                {tab === 'temperature' ? '🌡 Temperature' : tab === 'humidity' ? '💧 Humidity' : '🔍 Why it dropped'}
              </button>
            ))}
          </div>

          {/* Tab content */}
          <div className="p-6 animate-fade-in" key={activeTab}>
            {activeTab === 'temperature' && (
              <div>
                <div className="flex items-center gap-4 mb-4 text-xs">
                  <div className="flex items-center gap-1.5">
                    <span className="w-3 h-0.5 rounded-full inline-block bg-fresh" />
                    <span className="text-muted">Temperature</span>
                  </div>
                  <div className="flex items-center gap-1.5">
                    <span className="w-3 h-2 rounded inline-block opacity-30 bg-fresh" />
                    <span className="text-muted">Safe band ({s.ideal_temp_range?.[0]}–{s.ideal_temp_range?.[1]}°C)</span>
                  </div>
                </div>
                <ResponsiveContainer width="100%" height={220}>
                  <LineChart data={chartData} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#F0EDE6" />
                    <XAxis
                      dataKey="h"
                      tickFormatter={v => `\${v}h`}
                      tick={{ fontSize: 11, fill: '#6B7568' }}
                    />
                    <YAxis
                      tickFormatter={v => `\${v}°`}
                      tick={{ fontSize: 11, fill: '#6B7568' }}
                      domain={[0, 'auto']}
                    />
                    <Tooltip content={<CustomTooltip />} />
                    {/* Safe band */}
                    {s.ideal_temp_range && (
                      <ReferenceArea y1={s.ideal_temp_range[0]} y2={s.ideal_temp_range[1]} fill="#2F9E5B" fillOpacity={0.08} />
                    )}
                    <Line
                      type="monotone"
                      dataKey="temp"
                      stroke="var(--color-fresh)"
                      strokeWidth={2.5}
                      dot={false}
                      activeDot={{ r: 4, fill: 'var(--color-fresh)' }}
                    />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            )}

            {activeTab === 'humidity' && (
              <div className="flex flex-col items-center justify-center h-40 gap-2">
                <div className="text-3xl">💧</div>
                <p className="text-sm font-medium text-green-black">
                  Avg relative humidity: {chartData.length ? Math.round(chartData.reduce((sum: number, c: any) => sum + c.humidity, 0) / chartData.length) : '--'}%
                </p>
                <p className="text-xs text-muted">
                  View humidity trends across the cold chain journey
                </p>
              </div>
            )}

            {activeTab === 'why' && (
               <div className="space-y-0">
                 {breakdown.length === 0 ? (
                   <p className="text-sm text-muted py-4">No significant anomalies detected yet.</p>
                 ) : (
                   breakdown.map((step: any, i: number) => {
                     // Determine status
                     const status = step.burn_rate > 3 ? 'critical' : step.burn_rate > 1.5 ? 'caution' : 'info';
                     return (
                       <div key={i} className="flex gap-4">
                         <div className="flex flex-col items-center">
                           <div
                             className="w-8 h-8 rounded-full flex items-center justify-center text-sm shrink-0"
                             style={{
                               background:
                                 status === 'critical' ? 'var(--color-critical-bg)' :
                                 status === 'caution' ? 'var(--color-caution-bg)' : 'var(--color-sage-light)',
                             }}
                           >
                             {status === 'critical' ? '🌡' : status === 'caution' ? '⚡' : '📊'}
                           </div>
                           {i < breakdown.length - 1 && (
                             <div className="w-0.5 flex-1 my-1 bg-border" />
                           )}
                         </div>
                         <div className="pb-6">
                           <p className="text-sm font-semibold mb-1 text-green-black">
                             {new Date(step.time).toLocaleString([], { hour: '2-digit', minute:'2-digit' })}
                           </p>
                           <p className="text-xs leading-relaxed text-muted">
                             Temp: {step.temp_c}°C / Burn Rate: {step.burn_rate}x
                           </p>
                         </div>
                       </div>
                     )
                   })
                 )}
               </div>
             )}
          </div>
        </div>

        {/* AI Insight card */}
        <div
          className="rounded-2xl p-5 mb-6 flex items-start gap-3"
          style={{ background: 'var(--color-sage-light)', border: '1px solid var(--color-sage)' }}
        >
          <span className="text-xl">✨</span>
          <div>
            <p className="text-sm font-semibold mb-0.5 text-leaf">
              AI Insight
            </p>
            <p className="text-sm text-green-black" style={{ lineHeight: 1.6 }}>
              {insightText}
            </p>
          </div>
        </div>

        {/* New alert from spike (derived from alerts API if within last 2 minutes and critical) */}
        {data.alerts && data.alerts.some((a: any) => a.severity === 'critical' && (Date.now() - new Date(a.created_at).getTime() < 120000)) && (
          <div
            className="rounded-2xl p-4 mb-6 flex items-center gap-3 animate-scale-in"
            style={{ background: 'var(--color-critical-bg)', border: '1px solid #F5C6C7' }}
          >
            <span className="text-red-500 text-lg">🔔</span>
            <p className="text-sm font-medium" style={{ color: '#C0181D' }}>
              New alert: Critical temperature spike logged — price markdown auto-applied to all retailers
            </p>
          </div>
        )}
      </div>

      {/* Demo simulator panel */}
      <div
        className="fixed bottom-6 right-6 z-40"
        style={{ maxWidth: 320 }}
      >
        <div
          className="bg-card rounded-2xl border border-border overflow-hidden"
          style={{ boxShadow: '0 8px 32px rgba(31,42,31,0.14)' }}
        >
          <button
            onClick={() => setSimPanelOpen(o => !o)}
            className="w-full flex items-center justify-between px-4 py-3 text-sm font-semibold border-b border-border text-green-black"
          >
            <span className="flex items-center gap-2">
              <span>🧪</span> Demo Simulator
            </span>
            <span className="text-muted">{simPanelOpen ? '▾' : '▴'}</span>
          </button>

          {simPanelOpen && (
            <div className="p-4">
              {simState === 'idle' && (
                <div className="flex flex-col gap-2">
                  <button
                    onClick={runNormal}
                    className="w-full py-2.5 rounded-xl text-sm font-medium border border-border transition-colors hover:bg-cream text-muted"
                  >
                    Normal readings
                  </button>
                  <button
                    onClick={runSpike}
                    className="w-full py-2.5 rounded-xl text-sm font-semibold text-white transition-all"
                    style={{ background: 'var(--color-tomato)', boxShadow: '0 4px 12px rgba(242,107,79,0.35)' }}
                  >
                    🌡 Simulate temperature spike
                  </button>
                </div>
              )}

              {simState === 'running' && (
                <div className="space-y-2">
                  {STEPPER_STEPS.map((step, i) => (
                    <div key={step} className="flex items-center gap-2.5">
                      <div
                        className="w-5 h-5 rounded-full flex items-center justify-center text-[10px] shrink-0"
                        style={{
                          background:
                            i < simStep ? 'var(--color-fresh-bg)' :
                            i === simStep ? 'var(--color-leaf)' : 'var(--color-border)',
                          color: i === simStep ? 'white' : i < simStep ? 'var(--color-leaf)' : 'var(--color-muted)',
                        }}
                      >
                        {i < simStep ? '✓' : i === simStep ? (
                          <span className="animate-spin-slow inline-block">⟳</span>
                        ) : i + 1}
                      </div>
                      <span
                        className="text-xs"
                        style={{
                          color: i <= simStep ? 'var(--color-green-black)' : 'var(--color-muted)',
                          fontWeight: i === simStep ? 600 : 400,
                        }}
                      >
                        {step}
                      </span>
                    </div>
                  ))}
                  {simError && (
                    <p className="text-xs text-critical mt-2">{simError}</p>
                  )}
                </div>
              )}

              {simState === 'done' && (
                <div className="flex flex-col items-center gap-2 py-2">
                  <div className="w-10 h-10 rounded-full bg-fresh-bg flex items-center justify-center text-lg text-leaf">
                    ✓
                  </div>
                  <p className="text-xs font-medium text-center text-leaf">
                    Simulation finished and UI refreshed!
                  </p>
                </div>
              )}

              {(simState === 'error' || simState === 'done') && (
                <button
                  onClick={resetDemo}
                  className="w-full mt-3 py-2 rounded-xl text-xs font-medium border border-border transition-colors hover:bg-cream text-muted"
                >
                  Reset demo
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

